# 기존 siglip_minimal_training_colab.ipynb 맨 아래 새 코드 셀에 전체를 붙여 실행합니다.
# 재학습 없음. 현재 연결된 무료 T4와 기존 Python 3.12 환경을 사용합니다.
from pathlib import Path
from datetime import datetime, timezone
import base64, hashlib, json, os, subprocess, uuid, zlib

TRAIN_ZIP_OVERRIDE = "/content/drive/MyDrive/inthon2026_train.zip"
SOURCE_RUN = Path("/content/drive/MyDrive/Inthon_SigLIP_2026/runs/siglip-minimal-training-v1")
CONTRACT_DIR = Path("/content/drive/MyDrive/Inthon_SigLIP_2026/contracts/starter80-20-seed2026-v1")
VERIFY_EPISODES = 834  # 기본: 같은 검증 834개를 원본 이미지부터 재계산. 빠른 점검은 64.
PYTHON = Path("/content/inthon-siglip-python312-cu128/bin/python")

if not Path('/content/drive/MyDrive').is_dir():
    from google.colab import drive
    drive.mount('/content/drive')
if not PYTHON.is_file():
    raise FileNotFoundError('기존 학습 노트북의 Python·패키지 준비 셀부터 실행하세요. 학습 셀을 다시 실행할 필요는 없습니다.')
for seed in [2026,2027,2028]:
    checkpoint=SOURCE_RUN/f'heads/minimal/seed{seed}/best.pt'
    if not checkpoint.is_file():
        raise FileNotFoundError('학습된 가중치가 없습니다: '+str(checkpoint))
TRAIN_ZIP = Path('/content/inthon-data/inthon2026_train.zip')
if not TRAIN_ZIP.is_file():
    TRAIN_ZIP = Path(TRAIN_ZIP_OVERRIDE)
if not TRAIN_ZIP.is_file():
    raise FileNotFoundError('원본 ZIP이 필요합니다: '+TRAIN_ZIP_OVERRIDE)
gpu=subprocess.check_output(['nvidia-smi','--query-gpu=name','--format=csv,noheader'],text=True)
if len(gpu.strip().splitlines())!=1 or 'T4' not in gpu:
    raise RuntimeError('무료 Colab T4 GPU 한 대에서 실행하세요: '+gpu)

PACKED = ''
raw=zlib.decompress(base64.b64decode(PACKED))
if hashlib.sha256(raw).hexdigest()!='ac8cddc19f182a7956bd368d95b5e9bed6edebca17db65cf6c5d6d06dc71ffdf':
    raise ValueError('내장 제출 코드 무결성 오류')
files=json.loads(raw)
tag=datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')+'-'+uuid.uuid4().hex[:6]
HELPER_DIR=Path('/content/inthon-minimal-submission-export')/tag
HELPER_DIR.mkdir(parents=True,exist_ok=False)
for name,source in files.items():
    (HELPER_DIR/name).write_text(source,encoding='utf-8',newline='\n')
OUTPUT_DIR=SOURCE_RUN/'submissions'/tag
WORK_DIR=Path('/content/inthon-minimal-submission-staging')/tag
LOG_PATH=SOURCE_RUN/('submission-export-'+tag+'.log')
cmd=[str(PYTHON),'-u',str(HELPER_DIR/'export_driver.py'),
     '--run-dir',str(SOURCE_RUN),'--contracts',str(CONTRACT_DIR),'--train-zip',str(TRAIN_ZIP),
     '--work-dir',str(WORK_DIR),'--output-dir',str(OUTPUT_DIR),'--episodes',str(VERIFY_EPISODES)]
print('기존 모델 3개를 재사용합니다. 추가 학습은 없습니다.')
print('저장 폴더:',OUTPUT_DIR)
print('원본 이미지 검증:',VERIFY_EPISODES,'개 / 무료 T4')
with LOG_PATH.open('w',encoding='utf-8') as log:
    process=subprocess.Popen(cmd,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,bufsize=1)
    try:
        for line in process.stdout:
            print(line,end='');log.write(line);log.flush()
        returncode=process.wait()
        if returncode:
            raise subprocess.CalledProcessError(returncode,cmd)
    except BaseException:
        if process.poll() is None:
            process.terminate();process.wait()
        print('실행 기록:',LOG_PATH)
        raise
SUBMISSION_ZIP=OUTPUT_DIR/'siglip_minimal_3seed_submission.zip'
print('완료. 채점 사이트에는 아래 ZIP만 직접 제출하세요:')
print(SUBMISSION_ZIP)
print('ZIP 크기:',round(SUBMISSION_ZIP.stat().st_size/2**20,1),'MiB')
print('오프라인 검증 보고서:',OUTPUT_DIR/'offline_verification.json')
